export const stitchHtml_conditions = "<header class=\"bg-surface/70 backdrop-blur-xl dark:bg-surface-dim/70 docked full-width top-0 sticky z-50 shadow-sm shadow-primary/10\">\n<div class=\"flex justify-between items-center w-full px-gutter py-sm max-w-container-max mx-auto\">\n<div class=\"text-headline-md font-headline-md font-bold text-primary dark:text-primary-fixed\">Thrive with Sharuja</div>\n\n<button class=\"md:hidden text-primary\">\n<span class=\"material-symbols-outlined\">menu</span>\n</button>\n</div>\n</header>\n<main class=\"relative\">\n\n<section class=\"relative min-h-[614px] flex items-center pt-xl overflow-hidden\">\n<div class=\"absolute inset-0 z-0 overflow-hidden\">\n<div class=\"parallax-bg absolute -top-20 -right-20 w-[600px] h-[600px] bg-primary-fixed/20 rounded-full blur-3xl\"></div>\n<div class=\"parallax-bg absolute top-40 -left-20 w-[400px] h-[400px] bg-soft-blue-fixed/20 rounded-full blur-3xl\"></div>\n</div>\n<div class=\"relative z-10 max-w-container-max mx-auto px-gutter grid grid-cols-1 lg:grid-cols-2 gap-lg items-center\">\n<div class=\"space-y-md\">\n<span class=\"inline-block px-md py-xs bg-primary-fixed text-on-primary-fixed rounded-full text-caption font-caption tracking-wider\">SUPPORTIVE CARE</span>\n<h1 class=\"text-display-lg font-display-lg text-primary leading-tight\">Understanding Your Child's Unique Journey</h1>\n<p class=\"text-body-lg font-body-lg text-on-surface-variant max-w-xl\">Every child blooms on their own timeline. We provide the expertise and empathy needed to navigate developmental complexities with confidence.</p>\n<div class=\"flex gap-md pt-md\">\n<button class=\"bg-primary text-on-primary px-lg py-md rounded-2xl font-label-md text-label-md shadow-lg shadow-primary/20 hover:scale-105 transition-transform\">Explore Conditions</button>\n<button class=\"border border-outline-variant text-primary px-lg py-md rounded-2xl font-label-md text-label-md hover:bg-surface-container transition-colors\">Parent Resources</button>\n</div>\n</div>\n<div class=\"relative group\">\n<div class=\"absolute inset-0 bg-primary-container/10 rounded-xl -rotate-3 scale-105 group-hover:rotate-0 transition-transform duration-500\"></div>\n<img alt=\"Therapeutic session with child\" class=\"relative z-10 w-full aspect-square object-cover rounded-xl shadow-xl\" data-alt=\"A warm and gentle scene of a pediatric therapist sitting on a soft rug with a young child, playing with colorful wooden building blocks. The lighting is bright and natural, coming from a large window in a clean, modern clinic with sage green accents. The overall mood is peaceful, professional, and family-centered, emphasizing growth and developmental progress.\" src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuCtD2QWb4FhznsQEBymMAbWPTZqr2kcNWpINr7sIra87xKSSqC0Bz0a5ScQjxXOeJIWKcqhnJgBV-x8Jpfc8-hZn_lKZ2P5wPczL39Pwx3-Ur2vNerJ4TOYYeD-PX9oXG-7zeaZYL_pRQbWCkV6NGlfsjuqpfZmqn40j158Ocl-pv08EwAlryWNJ1Dmln1IXlpyevVbilmwwiaHJw7HXG2RmlnNqt4VgOLvGEhhkaUCptQuVYzciCPysoxZSJGuh8DL91v0fKw6d0w\"/>\n</div>\n</div>\n</section>\n\n<section class=\"max-w-container-max mx-auto px-gutter py-xl flex flex-col md:flex-row gap-lg\">\n\n<aside class=\"w-full md:w-64 flex-shrink-0 sticky top-[100px] h-fit\">\n\n<div class=\"mt-lg p-md glass-card rounded-lg border border-outline-variant/30 hidden md:block\">\n<h4 class=\"font-headline-md text-headline-md text-primary mb-xs\">Need Help?</h4>\n<p class=\"text-caption font-caption text-on-surface-variant mb-md\">Our clinicians are here to provide a formal assessment and guidance.</p>\n<button class=\"w-full py-sm bg-primary-container text-on-primary rounded-xl text-label-md font-label-md hover:opacity-90\">Schedule Consultation</button>\n</div>\n</aside>\n\n<div class=\"flex-1 space-y-xl\">\n\n<div class=\"scroll-mt-32 space-y-md\" id=\"asd\">\n<div class=\"flex items-center gap-md\">\n<div class=\"w-12 h-12 bg-primary-fixed rounded-full flex items-center justify-center text-primary\">\n<span class=\"material-symbols-outlined\">psychology</span>\n</div>\n<h2 class=\"text-headline-lg font-headline-lg text-on-surface\">Autism Spectrum Disorder (ASD)</h2>\n</div>\n<div class=\"grid grid-cols-1 md:grid-cols-3 gap-md\">\n<div class=\"md:col-span-2 glass-card p-lg rounded-3xl border border-outline-variant/20 shadow-sm relative overflow-hidden group\">\n<div class=\"absolute -right-10 -top-10 w-40 h-40 bg-primary-fixed/10 rounded-full group-hover:scale-110 transition-transform\"></div>\n<h3 class=\"text-headline-md font-headline-md mb-sm\">A Spectrum of Strengths</h3>\n<p class=\"text-body-md font-body-md text-on-surface-variant mb-md\">ASD is a developmental condition that affects how people interact with others, communicate, learn, and behave. We focus on neuro-affirming care that celebrates unique perspectives while building practical life skills.</p>\n<div class=\"flex flex-wrap gap-sm\">\n<span class=\"px-md py-xs bg-surface-container text-on-surface rounded-full text-caption font-caption\">Social Interaction</span>\n<span class=\"px-md py-xs bg-surface-container text-on-surface rounded-full text-caption font-caption\">Communication Styles</span>\n<span class=\"px-md py-xs bg-surface-container text-on-surface rounded-full text-caption font-caption\">Repetitive Behaviors</span>\n</div>\n</div>\n<div class=\"bg-primary-container p-lg rounded-3xl text-on-primary-container flex flex-col justify-between\">\n<p class=\"font-headline-md text-headline-md italic\">\"Understanding the 'why' behind the behavior is the first step toward connection.\"</p>\n<div class=\"pt-lg flex items-center gap-sm\">\n<div class=\"w-10 h-10 rounded-full bg-primary-fixed\"></div>\n<div>\n<p class=\"text-label-md font-label-md text-white\">Sharuja K.</p>\n<p class=\"text-caption font-caption opacity-80\">Lead Specialist</p>\n</div>\n</div>\n</div>\n</div>\n\n<div class=\"py-md\">\n<p class=\"text-label-md font-label-md text-outline mb-md flex items-center gap-xs\">\n<span class=\"material-symbols-outlined text-[16px]\">touch_app</span>\n                            CLICK TO EXPLORE KEY AREAS\n                        </p>\n<div class=\"flex flex-wrap gap-lg\">\n<button class=\"bubble-float w-32 h-32 md:w-40 md:h-40 bg-primary-fixed/40 rounded-full flex flex-col items-center justify-center p-md text-center transition-all hover:bg-primary-fixed/60 hover:scale-105 active:scale-95 group relative shadow-md\" onclick=\"toggleBubble('bubble-1')\">\n<span class=\"material-symbols-outlined text-primary mb-xs\">spatial_tracking</span>\n<span class=\"text-caption font-caption font-bold text-primary\">Sensory Profile</span>\n<div class=\"hidden absolute top-full mt-sm left-1/2 -translate-x-1/2 w-64 bg-surface rounded-xl p-md shadow-xl border border-outline-variant/30 z-20 text-left\" id=\"bubble-1\">\n<p class=\"text-caption font-caption text-on-surface\">Identifying over-responsivity or under-responsivity to environmental stimuli like sound, touch, or light.</p>\n</div>\n</button>\n<button class=\"bubble-float w-32 h-32 md:w-40 md:h-40 bg-soft-blue-fixed/40 rounded-full flex flex-col items-center justify-center p-md text-center transition-all hover:bg-soft-blue-fixed/60 hover:scale-105 active:scale-95 group relative shadow-md\" onclick=\"toggleBubble('bubble-2')\" style=\"animation-delay: 1s\">\n<span class=\"material-symbols-outlined text-tertiary mb-xs\">diversity_3</span>\n<span class=\"text-caption font-caption font-bold text-tertiary\">Social Prags</span>\n<div class=\"hidden absolute top-full mt-sm left-1/2 -translate-x-1/2 w-64 bg-surface rounded-xl p-md shadow-xl border border-outline-variant/30 z-20 text-left\" id=\"bubble-2\">\n<p class=\"text-caption font-caption text-on-surface\">Helping children navigate the subtle nuances of non-verbal cues and social expectations.</p>\n</div>\n</button>\n<button class=\"bubble-float w-32 h-32 md:w-40 md:h-40 bg-sage-fixed-dim/40 rounded-full flex flex-col items-center justify-center p-md text-center transition-all hover:bg-sage-fixed-dim/60 hover:scale-105 active:scale-95 group relative shadow-md\" onclick=\"toggleBubble('bubble-3')\" style=\"animation-delay: 2s\">\n<span class=\"material-symbols-outlined text-primary mb-xs\">list_alt</span>\n<span class=\"text-caption font-caption font-bold text-primary\">Executive Function</span>\n<div class=\"hidden absolute top-full mt-sm left-1/2 -translate-x-1/2 w-64 bg-surface rounded-xl p-md shadow-xl border border-outline-variant/30 z-20 text-left\" id=\"bubble-3\">\n<p class=\"text-caption font-caption text-on-surface\">Supporting planning, organization, and transitions between activities or thoughts.</p>\n</div>\n</button>\n</div>\n</div>\n</div>\n\n<div class=\"scroll-mt-32 space-y-md\" id=\"adhd\">\n<hr class=\"border-outline-variant/10\"/>\n<div class=\"flex items-center gap-md\">\n<div class=\"w-12 h-12 bg-secondary-container rounded-full flex items-center justify-center text-secondary\">\n<span class=\"material-symbols-outlined\">bolt</span>\n</div>\n<h2 class=\"text-headline-lg font-headline-lg text-on-surface\">ADHD &amp; Executive Functioning</h2>\n</div>\n<div class=\"grid grid-cols-1 md:grid-cols-2 gap-md\">\n<div class=\"glass-card p-lg rounded-3xl border border-outline-variant/20 shadow-sm\">\n<h3 class=\"text-headline-md font-headline-md mb-sm\">Harnessing Energy</h3>\n<p class=\"text-body-md font-body-md text-on-surface-variant\">ADHD is more than just hyperactivity. It's a different way the brain processes dopamine and handles regulation. We focus on \"Bottom-Up\" regulation to help kids find their calm center.</p>\n</div>\n<div class=\"relative rounded-3xl overflow-hidden h-48 md:h-full\">\n<img alt=\"Child focusing on task\" class=\"w-full h-full object-cover\" data-alt=\"A focused young girl with ADHD working on a colorful pattern puzzle on a wooden desk. The room is filled with soft natural light and organized sensory-friendly toys. The aesthetic is clean and modern, using a color palette of sage green and soft creams, conveying a sense of concentration and peaceful achievement.\" src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuAEe6s0U2hpnOuFGa_7qoXkswBFE6sEUamba5MgqagBxVBfAcX7xHscfO_gkDKFsqEPh4eAFLOG2XeHJWlrwnpx5xXiyQ0ciAqaLKkDydr16KW2DbebgkhXyHxfyvfkSw8bW2wANgZdPEsj2A_bZkzl6klqSVqTW5Bm5huOAlJc2xjZ6LqGMLhh4CRhAEQ-a9UOv5hvxjO5YqYw53-7PoBOJF6_KC0GgcSUvbxcvOeaIzH3xKwVuwi1cz29y9ynzWzPOqcL11lUAok\"/>\n</div>\n</div>\n</div>\n\n<div class=\"scroll-mt-32 space-y-md\" id=\"spd\">\n<hr class=\"border-outline-variant/10\"/>\n<div class=\"flex items-center gap-md\">\n<div class=\"w-12 h-12 bg-tertiary-fixed rounded-full flex items-center justify-center text-tertiary\">\n<span class=\"material-symbols-outlined\">back_hand</span>\n</div>\n<h2 class=\"text-headline-lg font-headline-lg text-on-surface\">Sensory Processing Disorder (SPD)</h2>\n</div>\n<div class=\"bg-surface-container p-lg rounded-3xl border border-outline-variant/10\">\n<div class=\"flex flex-col lg:flex-row gap-lg\">\n<div class=\"flex-1 space-y-md\">\n<h3 class=\"text-headline-md font-headline-md\">Making Sense of the World</h3>\n<p class=\"text-body-md font-body-md text-on-surface-variant\">Sensory Processing Disorder (SPD) is a condition where the brain has trouble receiving and responding to information that comes in through the senses. From picky eating to balance issues, we address the underlying sensory needs.</p>\n<ul class=\"grid grid-cols-1 sm:grid-cols-2 gap-sm\">\n<li class=\"flex items-center gap-xs text-on-surface-variant\"><span class=\"material-symbols-outlined text-primary text-sm\">check_circle</span>Proprioception</li>\n<li class=\"flex items-center gap-xs text-on-surface-variant\"><span class=\"material-symbols-outlined text-primary text-sm\">check_circle</span>Vestibular Input</li>\n<li class=\"flex items-center gap-xs text-on-surface-variant\"><span class=\"material-symbols-outlined text-primary text-sm\">check_circle</span>Tactile Sensitivity</li>\n<li class=\"flex items-center gap-xs text-on-surface-variant\"><span class=\"material-symbols-outlined text-primary text-sm\">check_circle</span>Interoception</li>\n</ul>\n</div>\n<div class=\"lg:w-1/3\">\n<div class=\"aspect-video bg-white rounded-2xl border border-outline-variant/30 flex items-center justify-center p-md\">\n<div class=\"text-center\">\n<span class=\"material-symbols-outlined text-display-lg text-primary opacity-30\">science</span>\n<p class=\"text-caption font-caption mt-sm\">Evidence-Based Sensory Integration</p>\n</div>\n</div>\n</div>\n</div>\n</div>\n</div>\n\n<div class=\"scroll-mt-32 space-y-md\" id=\"delays\">\n<hr class=\"border-outline-variant/10\"/>\n<div class=\"flex items-center gap-md\">\n<div class=\"w-12 h-12 bg-primary-fixed/50 rounded-full flex items-center justify-center text-primary\">\n<span class=\"material-symbols-outlined\">trending_up</span>\n</div>\n<h2 class=\"text-headline-lg font-headline-lg text-on-surface\">Developmental Delays</h2>\n</div>\n<div class=\"grid grid-cols-1 md:grid-cols-2 gap-md\">\n<div class=\"relative h-64 md:h-full rounded-3xl overflow-hidden\">\n<img alt=\"Developmental play\" class=\"w-full h-full object-cover\" data-alt=\"A toddler crawling across a soft play mat towards a smiling parent. The environment is a professional yet cozy pediatric therapy room with high-end wooden furniture and soft lighting. The colors are muted sage and cream, creating an organic modern vibe. The scene captures a milestone moment of movement and developmental progress.\" src=\"https://lh3.googleusercontent.com/aida-public/AB6AXuACyZbUte5_ARflRATS6EtsKDAMkbjH6bsZfjJ3Qyf4ITHn456ScY_KUtpPN2qwmxefmGqTS14BT0xB6XuaLNOLwmHOaGmeTArwgiCornpYFKWeVdD_2xJNMvxZBETEvIh7YNLUYwqvsjV-304T-IRbVEe7614rIxhjjnx1GvCd0Wj7MmBQrtL0yWG2Az-1G6QqKNlwMZ1XuppjX3fL4zIht3PnoJ7s1_miqz35IlBUnBGqNm1UNt7vVeUM-qJomJ7BxrVC4w_vcDg\"/>\n</div>\n<div class=\"glass-card p-lg rounded-3xl border border-outline-variant/20 shadow-sm flex flex-col justify-center\">\n<h3 class=\"text-headline-md font-headline-md mb-sm\">Catching Up with Confidence</h3>\n<p class=\"text-body-md font-body-md text-on-surface-variant mb-md\">Sometimes a little extra support is all that's needed to reach that next milestone. We track progress across cognitive, social, and emotional domains using standardized tools and play-based assessment.</p>\n<button class=\"text-primary font-label-md text-label-md flex items-center gap-xs hover:gap-md transition-all\">View Milestone Guide <span class=\"material-symbols-outlined\">arrow_forward</span></button>\n</div>\n</div>\n</div>\n</div>\n</section>\n\n<section class=\"max-w-container-max mx-auto px-gutter py-xl\">\n<div class=\"bg-primary-container rounded-3xl p-xl text-center text-on-primary-container relative overflow-hidden\">\n<div class=\"absolute inset-0 opacity-10\">\n<div class=\"absolute top-0 left-0 w-64 h-64 bg-white rounded-full -translate-x-1/2 -translate-y-1/2\"></div>\n<div class=\"absolute bottom-0 right-0 w-96 h-96 bg-white rounded-full translate-x-1/3 translate-y-1/3\"></div>\n</div>\n<div class=\"relative z-10 max-w-2xl mx-auto space-y-md\">\n<h2 class=\"text-display-lg font-display-lg text-white\">Not sure where to start?</h2>\n<p class=\"text-body-lg font-body-lg opacity-90\">Every journey begins with a conversation. Let's discuss your concerns and see how we can help your child thrive.</p>\n<div class=\"flex flex-col sm:flex-row justify-center gap-md pt-md\">\n<button class=\"bg-white text-primary px-lg py-md rounded-2xl font-label-md text-label-md shadow-lg hover:scale-105 transition-transform\">Book a Free Screening</button>\n<button class=\"border border-white/30 text-white px-lg py-md rounded-2xl font-label-md text-label-md hover:bg-white/10 transition-colors\">Call Our Office</button>\n</div>\n</div>\n</div>\n</section>\n</main>";

